8	
9	namespace chatai_admin.Filter
10	{
11	    //[AttributeUsage(AttributeTargets.Method | AttributeTargets.Class)]
12	    public class ValidateJWTFilter : IActionFilter
13	    {
14	        private readonly ILogger<ValidateJWTFilter> _logger;
15	
16	        private readonly AppSettingConfig _appSettingConfig;
17	
18	        //允許Admin帳號種類代碼
19	        private readonly string[] _requiredAdminAccountType = new string[] { AccountTypeCodeEnum.Staff, AccountTypeCodeEnum.Student, AccountTypeCodeEnum.Faculty };
20	
21	        public ValidateJWTFilter(ILogger<ValidateJWTFilter> logger, AppSettingConfig appSettingConfig)
22	        {
23	            _logger = logger;
24	            _appSettingConfig = appSettingConfig;
25	        }
26	
27	        public void OnActionExecuting(ActionExecutingContext context)
28	        {
29	            //if (!IsJWTOnly(context)) return;
30	
31	            if (IsAllowAnonymous(context)) return;
32	
33	            if (!context.HttpContext.Request.Headers.TryGetValue("Authorization", out var encryptedSignature))
34	                throw new CustomException("缺少 Authorization Header.");
35	
36	            var authToken = encryptedSignature.ToNullString();
37	            if (string.IsNullOrEmpty(authToken) || !authToken.StartsWith("Bearer"))
38	                throw new CustomException("Invalid Authorization Header");
39	
40	            // 驗證 Token 是否有效
41	            if (!JWTHelper.ValidateToken(authToken, out var principal))
42	                throw new CustomException("Authorization驗證失敗");
43	
44	            var jwtInfo = JWTHelper.GetJwtInfo(authToken);
45	            if (!_requiredAdminAccountType.Any(x => x == jwtInfo.accountTypeCode) || !_appSettingConfig.AdminUsers!.Any(x => x == jwtInfo.accountName))
46	                throw new CustomException("沒有權限");
47	        }
48	
49	        public void OnActionExecuted(ActionExecutedContext context)
50	        {
51	            // 無需處理
52	        }
53	
54	        private static bool IsAllowAnonymous(ActionExecutingContext context)
55	        {
56	            return context.ActionDescriptor.EndpointMetadata
57	                .Any(em => em is AllowAnonymousAttribute);
58	        }
59	
60	        //private static bool IsJWTOnly(ActionExecutingContext context)
61	        //{
62	        //    return context.ActionDescriptor.EndpointMetadata
63	        //        .Any(em => em is JWTOnlyAttribute);
64	        //}
65	    }
66	}

1	using chatai.Core.Config;
2	using Microsoft.IdentityModel.Tokens;
3	using ntu.Common.Utility.Extension;
4	using System.IdentityModel.Tokens.Jwt;
5	using System.Security.Claims;
6	using System.Security.Cryptography;
7	using System.Text;
8	using static chatai.Core.Enumeration.SystemEnum;
9	
10	namespace chatai_admin.Helpers
11	{
12	    public class JWTHelper
13	    {
14	        private static IServiceProvider _serviceProvider;
15	        private static string _issuer = string.Empty;
16	        private static string _jwtSecret = string.Empty;
17	
18	        public static void Configure(IServiceProvider serviceProvider)
19	        {
20	            _serviceProvider = serviceProvider;
21	            _issuer = appSettingConfig.BaseUrl;
22	            _jwtSecret = appSettingConfig.JwtSecret;
23	        }
24	
25	        private static ILogger<JWTHelper> logger => _serviceProvider.GetRequiredService<ILogger<JWTHelper>>();
26	
27	        private static AppSettingConfig appSettingConfig => _serviceProvider.GetRequiredService<AppSettingConfig>();
28	
29	        /// <summary>
30	        /// 取得User Signing Key
31	        /// </summary>
32	        /// <param name="regNo"></param>
33	        /// <returns></returns>
34	        private static SymmetricSecurityKey GetUserKey(string regNo)
35	        {
36	            var keySource = Encoding.UTF8.GetBytes(_jwtSecret);
37	            using var hmac = new HMACSHA512(keySource);
38	            var userKey = hmac.ComputeHash(Encoding.UTF8.GetBytes(regNo));
39	            return new SymmetricSecurityKey(userKey);
40	        }
41	
42	        /// <summary>
43	        /// 產生Token
44	        /// </summary>
45	        /// <param name="accountName"></param>
46	        /// <param name="name"></param>
47	        /// <param name="accountTypeCode"></param>
48	        /// <param name="regNo"></param>
49	        /// <param name="expireMinutes"></param>
50	        /// <returns></returns>
51	        public static (string token, DateTime loginDate, DateTime expDate) GenerateToken(string accountName, string? name, string accountTypeCode, int expireMinutes = 480)
52	        {
53	            var utcNow = DateTimeOffset.UtcNow;
54	            var localNow = utcNow.ToOffset(TimeSpan.FromHours(8)).DateTime;
55	            var localExp = localNow.AddMinutes(expireMinutes);
56	
57	            var claims = new List<Claim>
58	            {
59	                new Claim(JwtRegisteredClaimNames.UniqueName, name.ToNullString().SubstringWithChinese(1, string.Empty)),
60	                new Claim(JwtRegisteredClaimNames.Sub, accountName),
61	                new Claim(JwtRegisteredClaimNames.Name, name),
62	                new Claim(JwtRegisteredClaimNames.Typ, accountTypeCode),
63	                new Claim(JwtRegisteredClaimNames.Jti, Guid.NewGuid().ToString()),
64	                new Claim(JwtRegisteredClaimNames.Iat, utcNow.ToUnixTimeSeconds().ToString(), ClaimValueTypes.Integer64),
65	                new Claim(JwtRegisteredClaimNames.Iss, _issuer),
66	            };
67	
68	            var signingKey = GetUserKey(accountName);
69	
70	            var jwt = new JwtSecurityToken(
71	                issuer: _issuer,
72	                claims: claims,
73	                notBefore: localNow,
74	                expires: localExp,
75	                signingCredentials: new SigningCredentials(signingKey, SecurityAlgorithms.HmacSha512Signature)
76	            );
77	
78	            var token = new JwtSecurityTokenHandler().WriteToken(jwt);
79	            return (token, localNow, localExp);
80	        }
81	
82	        /// <summary>
83	        /// 修改Token的reg_no
84	        /// </summary>
85	        /// <param name="originalAuthToken"></param>
86	        /// <param name="newRegNo"></param>
87	        /// <returns></returns>
88	        public static (string newToken, DateTime loginDate, DateTime expDate)? UpdateToken(string? originalAuthToken)
89	        {
90	            if (!ValidateToken(originalAuthToken, out var principal) || principal == null)
91	                return null;
92	
93	            var accountName = principal.FindFirst(ClaimTypes.NameIdentifier)?.Value;
94	            var name = principal.FindFirst(ClaimTypes.Name)?.Value;
95	            var accountTypeCode = principal.FindFirst(CustomClaimNames.AccountTypeCode)?.Value;
96	
97	            if (string.IsNullOrWhiteSpace(accountName) || string.IsNullOrWhiteSpace(name) || string.IsNullOrWhiteSpace(accountTypeCode))
98	                return null;
99	
100	            return GenerateToken(accountName, name, accountTypeCode);
101	        }
102	
103	
104	        /// <summary>
105	        /// 驗證Token
106	        /// </summary>
107	        /// <param name="authToken"></param>
108	        /// <param name="principal"></param>
109	        /// <returns></returns>
110	        public static bool ValidateToken(string authToken, out ClaimsPrincipal? principal)
111	        {
112	            principal = null;
113	
114	            try
115	            {
116	                var tokenHandler = new JwtSecurityTokenHandler();
117	                var token = authToken?.Split(' ').LastOrDefault();
118	
119	                if (string.IsNullOrWhiteSpace(token))
120	                {
121	                    logger.LogWarning("Token is null or empty.");
122	                    return false;
123	                }
124	
125	                var jwt = tokenHandler.ReadJwtToken(token);
126	                var accountName = jwt.Claims.FirstOrDefault(x => x.Type == JwtRegisteredClaimNames.Sub)?.Value;
127	
128	                if (string.IsNullOrWhiteSpace(accountName))
129	                {
130	                    logger.LogWarning("Missing Subject (accountName) in token.");
131	                    return false;
132	                }
133	
134	                principal = tokenHandler.ValidateToken(token, new TokenValidationParameters
135	                {
136	                    NameClaimType = ClaimTypes.NameIdentifier,
137	                    ValidateAudience = false,
138	                    ValidateLifetime = false, // 你也可以改成 true，看你要不要加時間驗證
139	                    ClockSkew = TimeSpan.Zero,
140	                    IssuerSigningKey = GetUserKey(accountName),
141	                    ValidateIssuer = true,
142	                    ValidIssuer = _issuer,
143	                }, out SecurityToken validatedToken);
144	
145	                var now = DateTime.UtcNow.AddSeconds(60);
146	                if (validatedToken is JwtSecurityToken jwtToken)
147	                {
148	                    if (jwtToken.ValidFrom > now || jwtToken.ValidTo < now)
149	                    {
150	                        logger.LogInformation($"Token expired. ValidFrom: {jwtToken.ValidFrom:yyyy/MM/dd HH:mm:ss}, Now: {now:yyyy/MM/dd HH:mm:ss}, ValidTo: {jwtToken.ValidTo:yyyy/MM/dd HH:mm:ss}");
151	                        return false;
152	                    }
153	                }
154	
155	                return true;
156	            }
157	            catch (Exception ex)
158	            {
159	                logger.LogError(ex, "Token validation failed.");
160	                return false;
161	            }
162	        }
163	
164	
165	        public static (string? accountName, string? accountTypeCode) GetJwtInfo(string authToken)
166	        {
167	            var handler = new JwtSecurityTokenHandler();
168	            var token = authToken?.Split(' ').LastOrDefault();
169	            var jwtToken = handler.ReadJwtToken(token);
170	
171	            var accountName = jwtToken.Claims.FirstOrDefault(x => x.Type == JwtRegisteredClaimNames.Sub)?.Value;
172	            var accountTypeCode = jwtToken.Claims.FirstOrDefault(x => x.Type == JwtRegisteredClaimNames.Typ)?.Value;
173	
174	            return (accountName, accountTypeCode);
175	        }
176	    }
177	}
