9	    public static class AuthorizeManagement
10	    {
11	        private static IServiceProvider _serviceProvider;
12	
13	        public static void Configure(IServiceProvider serviceProvider)
14	        {
15	            _serviceProvider = serviceProvider;
16	        }
17	
18	        private static IHttpContextAccessor _contextAccessor => _serviceProvider.GetRequiredService<IHttpContextAccessor>();
19	
20	        private static HttpContext Current => _contextAccessor!.HttpContext!;
21	
22	        /// <summary>
23	        /// 目前HTTP要求中的安全性資訊(User)
24	        /// </summary>
25	        private static IPrincipal User => Current.User;
26	
27	        /// <summary>
28	        /// 當前登入的使用者
29	        /// </summary>
30	        public static AppUser CurrentUser => new(User);
31	
32	        public static AppJwtUser? GetUserFromJwtHeader()
33	        {
34	            var httpContext = Current;
35	            var authHeader = httpContext.Request.Headers["Authorization"].FirstOrDefault();
36	            if (string.IsNullOrEmpty(authHeader) || !authHeader.StartsWith("Bearer ")) return null;
37	
38	            var token = authHeader.Substring("Bearer ".Length).Trim();
39	
40	            var handler = new JwtSecurityTokenHandler();
41	            var jwtToken = handler.ReadJwtToken(token);
42	
43	            var identity = new ClaimsIdentity(jwtToken.Claims, "jwt");
44	            var principal = new ClaimsPrincipal(identity);
45	
46	            return new AppJwtUser(principal);
47	        }
48	    }
