1	using chatai.Core.Enumeration;
2	using chatai_admin.Helpers;
3	using Microsoft.AspNetCore.Authentication;
4	using Microsoft.AspNetCore.Authorization;
5	using Microsoft.Extensions.Options;
6	using System.Security.Claims;
7	using System.Text.Encodings.Web;
8	
9	namespace chatai_admin.Handlers
10	{
11	    public class JWTAuthHandler : AuthenticationHandler<AuthenticationSchemeOptions>
12	    {
13	        public JWTAuthHandler(IOptionsMonitor<AuthenticationSchemeOptions> options, ILoggerFactory logger, UrlEncoder encoder, ISystemClock clock) : base(options, logger, encoder, clock)
14	        {
15	        }
16	
17	        protected override Task<AuthenticateResult> HandleAuthenticateAsync()
18	        {
19	            var endpoint = Context.GetEndpoint();
20	            if (endpoint?.Metadata.GetMetadata<IAllowAnonymous>() != null) return Task.FromResult(AuthenticateResult.NoResult());
21	
22	            var authToken = Context.Request.Cookies[SystemEnum.CookieKey.AuthToken];
23	
24	            if (string.IsNullOrEmpty(authToken) || !authToken.StartsWith("Bearer")) return Task.FromResult(AuthenticateResult.Fail("Invalid Authorization Header"));
25	
26	            try
27	            {
28	                ClaimsPrincipal? principal;
29	                JWTHelper.ValidateToken(authToken, out principal);
30	
31	                var ticket = new AuthenticationTicket(principal!, "Bearer");
32	                return Task.FromResult(AuthenticateResult.Success(ticket));
33	
34	            }
35	            catch (Exception ex)
36	            {
37	                Logger.LogError(ex, "Token validation failed.");
38	                return Task.FromResult(AuthenticateResult.Fail(ex));
39	            }
40	        }
41	
42	    }
43	}
