1	import { basePrefix } from './env'
2	
3	// 取得 JWT token
4	export function getToken() {
5	  return localStorage.getItem(`${basePrefix}jwt_token`)
6	}
7	
8	// 設定 JWT token
9	export function setToken(token) {
10	  localStorage.setItem(`${basePrefix}jwt_token`, token)
11	}
12	
13	export function removeToken() {
14	  localStorage.removeItem(`${basePrefix}jwt_token`)
15	}
16	
17	function base64UrlToBase64(str) {
18	  // 1. URL-safe 還原
19	  str = str.replace(/-/g, '+').replace(/_/g, '/')
20	  // 2. 補齊 padding
21	  const pad = str.length % 4
22	  if (pad) {
23	    str += '='.repeat(4 - pad)
24	  }
25	  return str
26	}
27	
28	// src/utils/jwt.js
29	export function isJwtValid(token) {
30	  if (!token) return false
31	  try {
32	    const base64 = base64UrlToBase64(token.split('.')[1])
33	    const payload = JSON.parse(atob(base64))
34	
35	    const now = Math.floor(Date.now() / 1000)
36	    return payload.exp && payload.exp > now
37	  } catch (e) {
38	    console.error("JWT decode error:", e)
39	    return false
40	  }
41	}
42	
43	// 解析 JWT payload
44	export function parseJwt(token) {
45	  if (!token) return null
46	  try {
47	    const base64Url = token.split('.')[1]
48	    if (!base64Url) return null
49	    let  base64 = base64Url.replace(/-/g, '+').replace(/_/g, '/')
50	    const pad = base64.length % 4
51	    if (pad) {
52	      base64 += '='.repeat(4 - pad)
53	    }
54	    const jsonPayload = decodeURIComponent(
55	      atob(base64)
56	        .split('')
57	        .map(c => '%' + ('00' + c.charCodeAt(0).toString(16)).slice(-2))
58	        .join('')
59	    )
60	    return JSON.parse(jsonPayload)
61	  } catch {
62	    return null
63	  }
64	}

1	using chatai.Adapter.Chatai.DTO;
2	using chatai.Core.Config;
3	using chatai.Core.Models.reponse.Qa;
4	using chatai.Core.Models.request.Qa;
5	using chatai.Core.Module;
6	using chatai_admin.Controllers.Base;
7	using Microsoft.AspNetCore.Mvc;
8	using ntu.Common.Utility.Exception;
9	using ntu.Common.Utility.Helper;
10	using static chatai.Core.Models.reponse.Qa.SearchResponse;
11	
12	namespace chatai_admin.Controllers
13	{
14	    [Route("api/[controller]/[action]")]
15	    public class QaController : BaseApiController
16	    {
17	        private readonly ILogger<QaController> _logger;
18	        private readonly AppSettingConfig _appSetting;
19	        private readonly IChataiModule _chataiModule;
20	        public QaController(ILogger<QaController> logger, AppSettingConfig appSetting, IChataiModule chataiModule)
21	        {
22	            _logger = logger;
23	            _appSetting = appSetting;
24	            _chataiModule = chataiModule;
25	        }
26	
27	        [HttpPost]
28	        public IActionResult Search([FromBody] SearchRequest request)
29	        {
30	            var model = new SearchResponse();
31	            (int totalCount, IEnumerable<Qa> data) result;
32	
33	            if (request.cid > 0)
34	                result = _chataiModule.GetQaListForCid(request.page_size, request.page, request.cid, request.value);
35	            else
36	                result = _chataiModule.GetQaList(request.page_size, request.page, request.value);
37	
38	            var qa_categoryListAll = _chataiModule.GetQa_categoryListAll();
39	            var qaResponseList = AutoMapperHelper.MapList<Qa, QaResponse>(result.data.ToList());
40	
41	            qaResponseList.ForEach(x =>
42	            {
43	                x.cname = qa_categoryListAll.FirstOrDefault(y => y.cid == x.cid)?.cname;
44	            });
45	
46	            model.Items = qaResponseList;
47	            model.TotalCount = result.totalCount;
48	
49	            return Ok(model);
50	        }
51	
52	        [HttpPost]
53	        public IActionResult Save([FromBody] SaveRequest request)
54	        {
55	            if (string.IsNullOrEmpty(request.question))
56	                throw new CustomException("請填寫問題描述");
57	
58	            var result = new QaResponse();
59	
60	            if (request.type != chatai.Adapter.Chatai.Enumeration.QaEnum.TypeSts.organizer)
61	            {
62	                request.tel = string.Empty;
63	                request.email = string.Empty;
64	            }
65	
66	            if (request.id > 0)
67	            {
68	                var qaData = _chataiModule.GetQaData(request.id);
69	
70	                if (qaData == null)
71	                    throw new CustomException("找不到該筆資料");
72	
73	                qaData.cid = request.cid;
74	                qaData.type = request.type;
75	                qaData.question = request.question.Trim();
76	                qaData.answer = request.answer;
77	                qaData.tel = request.tel;
78	                qaData.email = request.email;
79	
80	                qaData.state = request.state;
81	
82	                qaData.update_by = this.AppJwtUser!.Name;
83	                qaData.update_date = DateTime.Now;
84	
85	                _chataiModule.UpdateQa(request);
86	
87	                result = AutoMapperHelper.Map<Qa, QaResponse>(qaData);
88	            }
89	            else
90	            {
91	                request.is_del = false;
92	                request.create_by = this.AppJwtUser!.Name;
93	                request.update_by = this.AppJwtUser!.Name;
94	                request.create_date = DateTime.Now;
95	                request.update_date = DateTime.Now;
96	
97	                _chataiModule.AddQa(request);
98	
99	                result = AutoMapperHelper.Map<Qa, QaResponse>(request);
100	            }
101	
102	            var qa_categoryListAll = _chataiModule.GetQa_categoryListAll();
103	            result.cname = qa_categoryListAll.FirstOrDefault(y => y.cid == result.cid)?.cname;
104	
105	            return Ok(result);
106	        }
107	
108	        [HttpPost]
109	        public IActionResult Delete([FromBody] DeleteRequest request)
110	        {
111	            var qaData = _chataiModule.GetQaData(request.id);
112	
113	            if (qaData == null)
114	                throw new CustomException("找不到該筆資料");
115	
116	            qaData.is_del = true;
117	            qaData.update_by = this.AppJwtUser!.Name;
118	            qaData.update_date = DateTime.Now;
119	
120	            var result = _chataiModule.UpdateQa(qaData);
121	
122	            if (!result)
123	                throw new CustomException("刪除失敗，請重新再試");
124	
125	            return Ok();
126	        }
127	
128	        [HttpPost]
129	        public IActionResult UpdateState([FromBody] UpdateStateRequest request)
130	        {
131	            var qaData = _chataiModule.GetQaData(request.id);
132	
133	            if (qaData == null)
134	                throw new CustomException("找不到該筆資料");
135	
136	            qaData.state = request.state;
137	            qaData.update_by = this.AppJwtUser!.Name;
138	            qaData.update_date = DateTime.Now;
139	
140	            var result = _chataiModule.UpdateQa(qaData);
141	
142	            if (!result)
143	                throw new CustomException("儲存失敗，請重新再試");
144	
145	            return Ok(result);
146	        }
147	    }
148	}
