5	
6	namespace chatai_admin.Controllers
7	{
8	    /// <summary>
9	    /// flowId=6（Gemini File Search RAG）的共用文件管理，跟 QA 管理完全獨立。
10	    /// 這裡沒有額外的權限標記，是因為全站的 ValidateJWTFilter 已經全域驗證
11	    /// JWT + AdminUsers 名單，跟其他管理端 controller（例如 QaController）一致。
12	    /// </summary>
13	    [Route("api/[controller]/[action]")]
14	    public class GeminiDocumentController : BaseApiController
15	    {
16	        private static readonly string[] AllowedExtensions =
17	            { ".pdf", ".txt", ".md", ".csv", ".docx", ".jpg", ".jpeg", ".png", ".webp" };
18	
19	        private const long MaxFileSizeBytes = 50 * 1024 * 1024; // 50MB
20	
21	        private readonly IGeminiFileSearchService _geminiService;
22	        private readonly ILogger<GeminiDocumentController> _logger;
23	
24	        public GeminiDocumentController(IGeminiFileSearchService geminiService, ILogger<GeminiDocumentController> logger)
25	        {
26	            _geminiService = geminiService;
27	            _logger = logger;
28	        }
29	
30	        [HttpPost]
31	        public async Task<IActionResult> List()
32	        {
33	            var documents = await _geminiService.ListSharedDocumentsAsync();
34	            return Ok(documents);
35	        }
36	
37	        [HttpPost]
38	        public async Task<IActionResult> Upload(IFormFile file)
39	        {
40	            if (file == null || file.Length == 0)
41	                throw new CustomException("未選擇檔案");
42	
43	            if (file.Length > MaxFileSizeBytes)
44	                throw new CustomException("檔案大小超過 50MB 上限");
45	
46	            var ext = Path.GetExtension(file.FileName).ToLowerInvariant();
47	            if (!AllowedExtensions.Contains(ext))
48	                throw new CustomException($"不支援的檔案格式，只允許：{string.Join(", ", AllowedExtensions)}");
49	
50	            byte[] fileBytes;
51	            using (var stream = new MemoryStream())
52	            {
53	                await file.CopyToAsync(stream);
54	                fileBytes = stream.ToArray();
55	            }
56	
57	            var mimeType = string.IsNullOrEmpty(file.ContentType) ? "application/octet-stream" : file.ContentType;
58	            var adminAccount = AppJwtUser?.AccountName ?? "unknown-admin";
59	
60	            try
61	            {
62	                await _geminiService.UploadAndIndexAsync(fileBytes, mimeType, file.FileName, GeminiFileSearchService.SharedUserId);
63	                _logger.LogInformation("管理端上傳共用文件完成: admin={Admin} file={FileName}", adminAccount, file.FileName);
64	            }
65	            catch (Exception ex)
66	            {
67	                _logger.LogError(ex, "管理端上傳共用文件失敗: admin={Admin} file={FileName}", adminAccount, file.FileName);
68	                throw new CustomException($"上傳或索引失敗：{ex.Message}");
69	            }
70	
71	            return Ok(new { message = $"「{file.FileName}」已上傳並完成索引。" });
72	        }
73	
74	        public class DeleteRequest
75	        {
76	            public string DocumentName { get; set; } = "";
77	        }
78	
79	        [HttpPost]
80	        public async Task<IActionResult> Delete([FromBody] DeleteRequest request)
81	        {
82	            if (string.IsNullOrEmpty(request.DocumentName))
83	                throw new CustomException("缺少文件名稱");
84	
85	            var adminAccount = AppJwtUser?.AccountName ?? "unknown-admin";
86	
87	            try
88	            {
89	                await _geminiService.DeleteDocumentAsync(request.DocumentName);
90	                _logger.LogInformation("管理端刪除共用文件: admin={Admin} document={DocumentName}", adminAccount, request.DocumentName);
91	            }
92	            catch (Exception ex)
93	            {
94	                _logger.LogError(ex, "管理端刪除共用文件失敗: admin={Admin} document={DocumentName}", adminAccount, request.DocumentName);
95	                throw new CustomException($"刪除失敗：{ex.Message}");
96	            }
97	
98	            return Ok();
99	        }
100	    }
101	}
